'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['setHovered']);
const { setHovered } = api;
assert.strictEqual(typeof setHovered, 'function');

const cards = [
  { id: 'a', label: 'Alpha', accent: 'red' },
  { id: 'b', label: 'Beta', accent: 'blue' },
  { id: 'c', label: 'Gamma', accent: 'green' }
];
const snapshot = cards.map((card) => ({ ...card }));
const hovered = setHovered(cards, 'b', true);
assert.deepStrictEqual(hovered, [
  { id: 'a', label: 'Alpha', accent: 'red' },
  { id: 'b', label: 'Beta', accent: 'highlight' },
  { id: 'c', label: 'Gamma', accent: 'green' }
]);
assert.deepStrictEqual(cards, snapshot);
assert.notStrictEqual(hovered, cards);
for (let index = 0; index < cards.length; index += 1) {
  assert.notStrictEqual(hovered[index], cards[index]);
}

const unhovered = setHovered(cards, 'a', false);
assert.deepStrictEqual(unhovered, [
  { id: 'a', label: 'Alpha', accent: 'normal' },
  { id: 'b', label: 'Beta', accent: 'blue' },
  { id: 'c', label: 'Gamma', accent: 'green' }
]);
unhovered[1].label = 'Changed';
unhovered[2].accent = 'Changed';
assert.deepStrictEqual(cards, snapshot);

const unusualIds = [
  { id: '', label: '', accent: '' },
  { id: '__proto__', label: 'Prototype', accent: 'custom' }
];
assert.deepStrictEqual(setHovered(unusualIds, '', true), [
  { id: '', label: '', accent: 'highlight' },
  { id: '__proto__', label: 'Prototype', accent: 'custom' }
]);

for (const invalidCards of [undefined, null, {}, 'cards', 1]) {
  assert.throws(() => setHovered(invalidCards, 'a', true), TypeError);
}
for (const invalidCard of [null, [], 'card', 1]) {
  assert.throws(() => setHovered([invalidCard], 'a', true), TypeError);
}
for (const malformed of [
  { id: 1, label: 'A', accent: 'x' },
  { id: 'a', label: null, accent: 'x' },
  { id: 'a', label: 'A', accent: false },
  { id: 'a', label: 'A' }
]) {
  assert.throws(() => setHovered([malformed], 'a', true), TypeError);
}
assert.throws(() => setHovered([
  { id: 'dup', label: 'A', accent: 'x' },
  { id: 'dup', label: 'B', accent: 'y' }
], 'dup', true), Error);
assert.throws(() => setHovered([], 'missing', true), Error);
assert.throws(() => setHovered(cards, 'missing', true), Error);
assert.throws(() => setHovered(cards, null, true), TypeError);
assert.throws(() => setHovered(cards, 'a', 1), TypeError);

